34	: ${NUM_CRITIC_ONLY_STEPS:=30}        # critic-only warmup; actor frozen
35	: ${CRITIC_EXCLUDE_OLP:=1}            # critic regresses reward WITHOUT the overlong penalty
36	: ${GAMMA:=1.0}                       # must be 1 for the length-adaptive lambda
37	
38	# ---- PPO -------------------------------------------------------------------
39	: ${LR:=1e-6}
40	: ${CRITIC_LR:=5e-6}
41	: ${CRITIC_LR_WARMUP_ITERS:=10}
42	: ${EPS_CLIP:=0.2}
43	: ${EPS_CLIP_HIGH:=0.28}              # clip-higher
44	: ${VALUE_CLIP:=0.2}
45	: ${OVERLONG_BUFFER_LEN:=25395}       # DAPO soft overlong punishment: last 20% of 126976
46	: ${OVERLONG_PENALTY_FACTOR:=1.0}
47	: ${TIS_CLIP_LOW:=0.5}                # truncated importance sampling (IcePop)
48	: ${TIS_CLIP:=5.0}
49	
50	# ---- parallelism / memory --------------------------------------------------
51	: ${TENSOR_MODEL_PARALLEL_SIZE:=1}
52	: ${CONTEXT_PARALLEL_SIZE:=4}
53	: ${MAX_TOKENS_PER_GPU:=16000}      # microbatch packing target, x CONTEXT_PARALLEL_SIZE, not a
54	                                    # hard cap: a single 129024-token sample still goes through
55	                                    # alone, which is what sets the memory high-water mark
56	: ${LOG_PROBS_CHUNK_SIZE:=2048}
57	: ${SGLANG_MEM_FRACTION:=0.83}
58	: ${SGLANG_MAX_RUNNING_REQUESTS:=64}
59	: ${SGLANG_MAX_TOTAL_TOKENS:=1441792} # ~11 full-128k sequences per engine
60	: ${SGLANG_ATTENTION_BACKEND:=fa3}
61	
62	# ---- DSpark speculative decoding (optional; empty = off; needs an SGLang build with DSpark,
63	#      not in the community image) ------------------------------------------------------
64	: ${DSPARK_DRAFT_MODEL_PATH:=}
65	: ${DSPARK_BLOCK_SIZE:=7}
66	: ${DSPARK_DRAFT_WINDOW:=4096}
67	
68	# ---- eval / checkpoint -----------------------------------------------------
69	: ${EVAL_INTERVAL:=1000}              # the reference run evaluated offline from HF exports instead
70	: ${EVAL_TEMPERATURE:=1.0}
71	: ${EVAL_TOP_P:=0.95}
72	: ${N_SAMPLES_PER_EVAL_PROMPT:=4}
73	: ${SAVE_INTERVAL:=5}
74	: ${SAVE_RETAIN_INTERVAL:=$((SAVE_INTERVAL * 20000))}
75	                                      # keep only the latest torch_dist ckpt (~63GB actor+critic).
76	                                      # Megatron pins every iteration that is a multiple of this and
77	                                      # rotates the rest away; rollout ids are 0-based, so a huge
78	                                      # multiple of SAVE_INTERVAL never hits a milestone and nothing
79	                                      # is pinned. Long-term archiving is HF_SAVE_INTERVAL, not this.
80	: ${HF_SAVE_INTERVAL:=5}              # HF export of the actor every 5 steps (0 = off)
81	
82	# ---- post-hoc analysis dumps -----------------------------------------------
83	# Empty (the default) = no dump. Set to a directory to record, per step, the rollout
84	# trajectories (rollout_data/) and the per-token values / advantages / returns
85	# (train_data/), plus policy_loss_debug/ and the IcePop scatter samples. Budget roughly
86	# 1.5 GB per step at this batch size and response length.
87	: ${DUMP_DIR:=}
88	: ${ICEPOP_DUMP_STEPS:=}              # e.g. "10 50 100"; empty keeps the miles default
89	
90	# ---- tracking --------------------------------------------------------------
91	: ${USE_WANDB:=0}
92	: ${USE_SWANLAB:=0}
