"""Deterministic exact-arithmetic Countdown reward for JustRL-II / Miles."""
from __future__ import annotations

import ast
import json
import re
from fractions import Fraction

ANSWER_RE = re.compile(r"<answer>(.*?)</answer>", flags=re.DOTALL)
ALLOWED_CHARS_RE = re.compile(r"[0-9+\-*/()\s]+")


def _eval_ast(node: ast.AST, used: list[int]) -> Fraction:
    if isinstance(node, ast.Expression):
        return _eval_ast(node.body, used)
    if isinstance(node, ast.Constant) and type(node.value) is int:
        used.append(node.value)
        return Fraction(node.value)
    if isinstance(node, ast.BinOp):
        left = _eval_ast(node.left, used)
        right = _eval_ast(node.right, used)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            if right == 0:
                raise ZeroDivisionError("division by zero")
            return left / right
        raise ValueError("unsupported binary op")
    raise ValueError("disallowed ast node")


def score_countdown(solution_str: str, ground_truth) -> float:
    if not isinstance(solution_str, str) or ground_truth is None:
        return 0.0
    if isinstance(ground_truth, str):
        try:
            gt = json.loads(ground_truth)
        except json.JSONDecodeError:
            return 0.0
    elif isinstance(ground_truth, dict):
        gt = ground_truth
    else:
        return 0.0
    matches = ANSWER_RE.findall(solution_str)
    if not matches:
        return 0.0
    expr = matches[-1].strip()
    expr = (
        expr.replace("\\times", "*")
        .replace("\\div", "/")
        .replace("\u00d7", "*")
        .replace("\u00f7", "/")
    )
    if "=" in expr:
        expr = expr.split("=")[0].strip()
    if not expr or len(expr) > 256 or not ALLOWED_CHARS_RE.fullmatch(expr):
        return 0.0
    try:
        tree = ast.parse(expr, mode="eval")
        used: list[int] = []
        val = _eval_ast(tree, used)
    except (SyntaxError, ZeroDivisionError, ValueError, RecursionError):
        return 0.0
    expected_nums = sorted(int(x) for x in gt["numbers"])
    if sorted(used) != expected_nums:
        return 0.0
    return 1.0 if val == Fraction(int(gt["target"])) else 0.0


async def compute_reward(args, sample, **kwargs) -> float:
    """Async custom reward entry point for Miles (--custom-rm-path)."""
    return float(score_countdown(getattr(sample, "response", ""), getattr(sample, "label", None)))

reported_loss = {
    "loss": loss.clone().detach(),
    "pg_loss": pg_loss.clone().detach(),
    "entropy_loss": entropy_loss.clone().detach(),
    "pg_clipfrac": pg_clipfrac.clone().detach(),
    "ppo_kl": ppo_kl.clone().detach(),
}
if ess_ratio_weight is None:
    reported_loss["ess_ratio"] = ess_ratio_sum.squeeze()
else:
    reported_loss["_weighted/ess_ratio"] = torch.stack([ess_ratio_sum.squeeze(), ess_ratio_weight.squeeze()])

if train_rollout_logprob_abs_diff is not None:
    reported_loss["train_rollout_logprob_abs_diff"] = train_rollout_logprob_abs_diff.clone().detach()
if train_rollout_kl is not None:
    reported_loss["train_rollout_kl"] = train_rollout_kl.clone().detach()

    with torch.no_grad():
        metric_diff = torch.where(
            active_tokens,
            torch.nan_to_num(abs_diff_raw, nan=0.0, posinf=0.0, neginf=0.0),
            abs_diff_raw.new_zeros(()),
        )
        flat_diff = metric_diff[active_tokens].detach().float()

        if args.calculate_per_token_loss:
            if flat_diff.numel() > 0:
                reported_loss["_logdiff_histogram"] = _make_logdiff_histogram(flat_diff)
                reported_loss["_logdiff_min_max"] = torch.stack([flat_diff.min(), flat_diff.max()]).to(
                    dtype=torch.float64
                )
            else:
                reported_loss["_logdiff_histogram"] = torch.zeros(
                    _LOGDIFF_HISTOGRAM_BINS + 1, device=flat_diff.device, dtype=torch.float64
                )
                reported_loss["_logdiff_min_max"] = torch.tensor(
                    [float("inf"), float("-inf")], device=flat_diff.device, dtype=torch.float64
                )
        elif flat_diff.numel() > 0:
            sorted_diff = flat_diff.sort().values
            n = sorted_diff.numel()
            for tag, q in [("p50", 0.5), ("p75", 0.75), ("p90", 0.9), ("p95", 0.95), ("p999", 0.999)]:
                idx = min(int(q * n), n - 1)
                reported_loss[f"logdiff_{tag}"] = sorted_diff[idx]
            reported_loss["logdiff_min"] = sorted_diff[0]
            reported_loss["logdiff_max"] = sorted_diff[-1]

        # Per-sample token-level max across active mask tokens.
        ref_list = batch["rollout_log_probs"]
        offset = 0
        per_sample_max_list = []
        for sample_lp, sample_mask in zip(ref_list, local_loss_mask_list, strict=True):
            seg_len = sample_lp.size(0)
            sample_mask = sample_mask.to(device=metric_diff.device, dtype=torch.bool)
            sample_diff = metric_diff[offset : offset + seg_len]
            if sample_mask.any():
                per_sample_max_list.append(sample_diff[sample_mask].max())
            elif args.calculate_per_token_loss:
                per_sample_max_list.append(flat_diff.new_full((), float("-inf")))
            offset += seg_len
        if per_sample_max_list:
            per_sample_max = torch.stack(per_sample_max_list)
            if args.calculate_per_token_loss:
                if parallel_state.cp.size > 1:
                    dist.all_reduce(per_sample_max, op=dist.ReduceOp.MAX, group=parallel_state.cp.group)
                finite_sample_max = per_sample_max[torch.isfinite(per_sample_max)]
                numerator = finite_sample_max.sum() if finite_sample_max.numel() > 0 else flat_diff.new_zeros(())
                denominator = flat_diff.new_tensor(float(finite_sample_max.numel()))
                if parallel_state.cp.size > 1 and parallel_state.cp.rank != 0:
                    numerator = numerator * 0
                    denominator = denominator * 0
                reported_loss["_weighted/logdiff_token_max_per_sample"] = torch.stack(
                    [numerator.squeeze(), denominator.squeeze()]
                )
            else:
                reported_loss["logdiff_token_max_per_sample"] = per_sample_max.mean()

        if flat_diff.numel() > 0:
            _accumulate_logdiff_histogram(flat_diff)
            if metric_diff.max().item() > 0.5:
                _log_extreme_logdiff_diagnostic(
                    flat_diff=metric_diff.detach().float(),
                    old_log_probs=old_log_probs,
                    rollout_log_probs=rollout_log_probs,
                    batch=batch,
                    args=args,
                )

if args.use_kl_loss:
    reported_loss["kl_loss"] = kl_loss.clone().detach()

if args.get_mismatch_metrics or args.use_tis:
    # Aggregate mismatch/TIS/RS related metrics with the *pre-RS* masks.
    # See comment above where `sum_of_sample_mean_for_mismatch_metrics` is defined.
    reported_loss["ois"] = sum_of_sample_mean_for_mismatch_metrics(ois).clone().detach()
    # Assume all metrics are already cloned and detached
    for metric_key, metric_value in tis_metrics.items():
        key_name = f"{metric_key}"
        reported_loss[key_name] = sum_of_sample_mean_for_mismatch_metrics(metric_value)

import logging
from collections.abc import Callable

import torch
import torch.distributed as dist
import torch.nn as nn
import torch.nn.functional as F

from .parallel import get_parallel_state

try:
    from fla.ops.cp import build_cp_context as _fla_build_cp_context
except ImportError:
    _fla_build_cp_context = None

logger = logging.getLogger(__name__)


def _parallel_rank(parallel_state, name: str) -> int:
    group_info = getattr(parallel_state, name, None)
    if group_info is not None and hasattr(group_info, "rank"):
        return group_info.rank

    legacy_name = f"{name}_rank"
    if hasattr(parallel_state, legacy_name):
        return getattr(parallel_state, legacy_name)

    raise AttributeError(f"ParallelState has neither {name}.rank nor {legacy_name}")


def _parallel_size(parallel_state, name: str) -> int:
    group_info = getattr(parallel_state, name, None)
    if group_info is not None and hasattr(group_info, "size"):
        return group_info.size

    legacy_name = f"{name}_size"
    if hasattr(parallel_state, legacy_name):
        return getattr(parallel_state, legacy_name)

    raise AttributeError(f"ParallelState has neither {name}.size nor {legacy_name}")


def get_logits_and_tokens_offset_with_cp(
    total_length: int,
    response_length: int,
    *args,
    qkv_format: str = "thd",
    max_seq_len: int | None = None,
):
    """
    All offsets start from the begining of the prompt.

    Compatible call forms:
    - get_logits_and_tokens_offset_with_cp(total_length, response_length, qkv_format, max_seq_len)
    - get_logits_and_tokens_offset_with_cp(total_length, response_length, parallel_state, qkv_format, max_seq_len)
    """
    parallel_state = None
    if args:
        first_arg = args[0]
        if isinstance(first_arg, str):
            qkv_format = first_arg
            if len(args) > 1:
                max_seq_len = args[1]
            if len(args) > 2:
                raise TypeError("Too many positional arguments for get_logits_and_tokens_offset_with_cp")
        else:
            parallel_state = first_arg
            if len(args) > 1:
                qkv_format = args[1]
            if len(args) > 2:
                max_seq_len = args[2]
            if len(args) > 3:
                raise TypeError("Too many positional arguments for get_logits_and_tokens_offset_with_cp")

    if parallel_state is None:
        parallel_state = get_parallel_state()

    cp_rank = _parallel_rank(parallel_state, "cp")
    cp_size = _parallel_size(parallel_state, "cp")
    assert cp_size > 1

    prompt_length = total_length - response_length
    if qkv_format == "thd":
        chunk_size = (total_length + 2 * cp_size - 1) // (2 * cp_size)
    else:
        assert max_seq_len is not None, "max_seq_len must be provided for qkv_format=bshd"
        chunk_size = (max_seq_len + 2 * cp_size - 1) // (2 * cp_size)

    # the offset of 2 chunks
    chunk_0 = (cp_rank * chunk_size, (cp_rank + 1) * chunk_size)
    chunk_1 = ((2 * cp_size - cp_rank - 1) * chunk_size, (2 * cp_size - cp_rank) * chunk_size)

    # the offset of 2 logits, note that the logits need a "-1".
    logits_0 = (max(chunk_0[0], prompt_length - 1), min(chunk_0[1], total_length - 1))
    logits_1 = (max(chunk_1[0], prompt_length - 1), min(chunk_1[1], total_length - 1))

    # when the sequence is empty, make an empty slice to continue the gradient flow.
    if logits_0[0] < logits_0[1]:
        token_0 = (logits_0[0] + 1, logits_0[1] + 1)
    else:
        logits_0 = (0, 0)
        token_0 = (0, 0)

    if logits_1[0] < logits_1[1]:
        token_1 = (logits_1[0] + 1, logits_1[1] + 1)
    else:
        logits_1 = (0, 0)
        token_1 = (0, 0)

    return chunk_size, (chunk_0, chunk_1), (logits_0, logits_1), (token_0, token_1)


def _slice_loss_mask_for_local_cp(
    total_length: int,
    response_length: int,
    loss_mask: torch.Tensor,
    qkv_format: str,
    max_seq_len: int | None,
) -> torch.Tensor:
    """Slice a per-sample response loss mask into this CP rank's local zigzag layout."""
    prompt_length = total_length - response_length
    _, _, _, tokens_offset = get_logits_and_tokens_offset_with_cp(
        total_length, response_length, qkv_format, max_seq_len
    )
    mask_0 = loss_mask[tokens_offset[0][0] - prompt_length : tokens_offset[0][1] - prompt_length]
    mask_1 = loss_mask[tokens_offset[1][0] - prompt_length : tokens_offset[1][1] - prompt_length]
    return torch.cat([mask_0, mask_1], dim=0)


def slice_loss_masks_for_local_cp(
    loss_masks: list[torch.Tensor],
    total_lengths: list[int],
    response_lengths: list[int],
    qkv_format: str = "thd",
    max_seq_lens: list[int] | None = None,
) -> list[torch.Tensor]:
    """Backward-compatible wrapper for local CP response mask slicing."""
    return get_local_response_loss_masks(total_lengths, response_lengths, loss_masks, qkv_format, max_seq_lens)


def get_sum_of_sample_mean(
    total_lengths: list[int],
    response_lengths: list[int],
    loss_masks: list[torch.Tensor],
    calculate_per_token_loss: bool = False,
    qkv_format: str = "thd",
    max_seq_lens: list[int] | None = None,
) -> Callable[[torch.Tensor], torch.Tensor]:
    """
    Calculate correct sample mean for CP
    """
    parallel_state = get_parallel_state()
    cp_size = parallel_state.cp.size
    if cp_size == 1:

        def sum_of_sample_mean(x: torch.Tensor) -> torch.Tensor:
            return sum(
                [
                    (x_i * loss_mask_i).sum() / torch.clamp_min(loss_mask_i.sum(), 1)
                    for x_i, loss_mask_i in zip(x.split(response_lengths, dim=0), loss_masks, strict=True)
                ]
            )

        def sum_of_token(x: torch.Tensor) -> torch.Tensor:
            return sum(
                [
                    (x_i * loss_mask_i).sum()
                    for x_i, loss_mask_i in zip(x.split(response_lengths, dim=0), loss_masks, strict=True)
                ]
            )

    else:
        cp_chunk_lengths = []
        chunked_loss_masks = []
        for i, (total_length, response_length, loss_mask) in enumerate(
            zip(total_lengths, response_lengths, loss_masks, strict=True)
        ):
            max_seq_len = max_seq_lens[i] if max_seq_lens is not None else None
            chunked_loss_masks.append(
                _slice_loss_mask_for_local_cp(total_length, response_length, loss_mask, qkv_format, max_seq_len)
            )
            cp_chunk_lengths.append(chunked_loss_masks[i].size(0))

        def sum_of_sample_mean(x: torch.Tensor) -> torch.Tensor:
            return sum(
                [
                    (x_i * chunked_loss_mask).sum() / torch.clamp_min(loss_mask.sum(), 1)
                    for x_i, chunked_loss_mask, loss_mask in zip(
                        x.split(cp_chunk_lengths, dim=0), chunked_loss_masks, loss_masks, strict=True
                    )
                ]
            )

        def sum_of_token(x: torch.Tensor) -> torch.Tensor:
            return sum(
                [
                    (x_i * chunked_loss_mask).sum()
                    for x_i, chunked_loss_mask in zip(
                        x.split(cp_chunk_lengths, dim=0), chunked_loss_masks, strict=True
                    )
                ]
            )

    return sum_of_sample_mean if not calculate_per_token_loss else sum_of_token


def get_local_response_loss_masks(
    total_lengths: list[int],
    response_lengths: list[int],
    loss_masks: list[torch.Tensor],
    qkv_format: str = "thd",
    max_seq_lens: list[int] | None = None,
) -> list[torch.Tensor]:
    """Return response loss masks aligned with this rank's local log-probs."""
    parallel_state = get_parallel_state()
    if parallel_state.cp.size == 1:
        return loss_masks

    local_masks = []
    for i, (total_length, response_length, loss_mask) in enumerate(
        zip(total_lengths, response_lengths, loss_masks, strict=True)
    ):
        max_seq_len = max_seq_lens[i] if max_seq_lens is not None else None
        local_masks.append(
            _slice_loss_mask_for_local_cp(total_length, response_length, loss_mask, qkv_format, max_seq_len)
        )

    return local_masks


def local_response_to_full(
    tensor: torch.Tensor,
    total_length: int,
    response_length: int,
    qkv_format: str = "thd",
    max_seq_len: int | None = None,
) -> torch.Tensor:
    """Scatter this CP rank's local response shard back into full-length response coordinates (missing positions zero-filled, no communication)."""
    _, _, logits_offset, _ = get_logits_and_tokens_offset_with_cp(
        total_length, response_length, qkv_format, max_seq_len
    )

    prompt_length = total_length - response_length

    chunk_0 = tensor[: logits_offset[0][1] - logits_offset[0][0]]
    chunk_1 = tensor[logits_offset[0][1] - logits_offset[0][0] :]
    assert chunk_1.shape[0] == logits_offset[1][1] - logits_offset[1][0]

    def zero(len: int) -> torch.Tensor:
        return torch.zeros(
            [len] + list(tensor.shape[1:]),
            dtype=tensor.dtype,
            device=tensor.device,
            requires_grad=True,
        )

    # logprob should be within the range of [prompt_length - 1, total_length - 1]
    if chunk_0.shape[0] == 0 and chunk_1.shape[0] == 0:
        # all empty
        full_tensor = zero(response_length)
    elif chunk_0.shape[0] != 0 and chunk_1.shape[0] == 0:
        # only first chunk
        left = zero(logits_offset[0][0] - (prompt_length - 1))
        right = zero(total_length - 1 - logits_offset[0][1])
        full_tensor = torch.cat([left, chunk_0, right], dim=0)
    elif chunk_0.shape[0] == 0 and chunk_1.shape[0] != 0:
        # only second chunk
        left = zero(logits_offset[1][0] - (prompt_length - 1))
        right = zero(total_length - 1 - logits_offset[1][1])
        full_tensor = torch.cat([left, chunk_1, right], dim=0)
    else:
        left = zero(logits_offset[0][0] - (prompt_length - 1))
        mid = zero(logits_offset[1][0] - logits_offset[0][1])
        right = zero(total_length - 1 - logits_offset[1][1])
        full_tensor = torch.cat([left, chunk_0, mid, chunk_1, right], dim=0)

    assert full_tensor.shape[0] == response_length, f"Expected {response_length}, got {full_tensor.shape}"
    return full_tensor


def all_gather_with_cp(
    tensor: torch.Tensor,
    total_length: int,
    response_length: int,
    qkv_format: str = "thd",
    max_seq_len: int | None = None,
) -> torch.Tensor:
    """
    Gather tensors across all ranks in the context parallel group.
    The first dimension of the output tensor will be the `response_length`.
    """
    parallel_state = get_parallel_state()
    cp_group = parallel_state.cp.group
    cp_size = parallel_state.cp.size

    if cp_size == 1:
        return tensor

    full_tensor = local_response_to_full(tensor, total_length, response_length, qkv_format, max_seq_len)
    full_tensor = dist.nn.all_reduce(full_tensor, group=cp_group)

def load(self, rollout_id=None):
    self.data_source.load(rollout_id)

def offload(self, tags: list[str] | None = None):
    self.health_monitoring_pause()
    if tags is not None:
        handles = [
            engine.release_memory_occupation.remote(tags=tags)
            for engine in self.rollout_engines
            if engine is not None
        ]
        return ray.get(handles) if handles else []
    for srv in self.servers.values():
        srv.offload()

def onload(self, tags: list[str] | None = None):
    for srv in self.servers.values():
        srv.onload(tags)

def health_monitoring_pause(self) -> None:
    for monitor in self._health_monitors:
        monitor.pause()

def health_monitoring_resume(self) -> None:
    for monitor in self._health_monitors:
        monitor.resume()

def onload_weights(self):
    for srv in self.servers.values():
        srv.onload_weights()

def onload_kv(self):
    for srv in self.servers.values():
        srv.onload_kv()

def recover_updatable_engines(self):
    """Restart any dead rollout engines and update num_new_engines for update_weights detection.

    Recovers the updatable model (the one that receives weight
    updates from training).
    """
    self.health_monitoring_pause()
    srv = self._get_updatable_server()
    if self.rollout_id == -1 or srv is None:
        engines = srv.engines if srv else []
        gpu_counts = srv.engine_gpu_counts if srv else []
        gpu_offsets = srv.engine_gpu_offsets if srv else []
        return engines, self.rollout_engine_lock, (srv.num_new_engines if srv else 0), gpu_counts, gpu_offsets

    srv.recover()
    return (
        srv.engines,
        self.rollout_engine_lock,
        srv.num_new_engines,
        srv.engine_gpu_counts,
        srv.engine_gpu_offsets,
    )

def clear_updatable_num_new_engines(self):
    # when fault tolerance is not enabled, we need to manually clear num_new_engines after update_weights
    srv = self._get_updatable_server()
    if srv:
        srv.num_new_engines = 0

def check_weights(self, action: str):
    return ray.get([engine.check_weights.remote(action=action) for engine in self.rollout_engines])

def _get_rollout_data(self, rollout_id):
    if self.args.load_debug_rollout_data:
        data = torch.load(
            self.args.load_debug_rollout_data.format(rollout_id=rollout_id),
            weights_only=False,
        )["samples"]
        data = [Sample.from_dict(sample) for sample in data]
        if (ratio := self.args.load_debug_rollout_data_subsample) is not None:
            original_num_rows = len(data)
            rough_subsample_num_rows = int(original_num_rows * ratio)
            data = data[: rough_subsample_num_rows // 2] + data[-rough_subsample_num_rows // 2 :]
            logger.info(
                f"Subsample loaded debug rollout data using {ratio=} and change num rows {original_num_rows} -> {len(data)}"
            )
        metrics = None
    else:
        if self.use_experimental_refactor:
            data = call_rollout_function(self.generate_rollout, RolloutFnTrainInput(rollout_id=rollout_id))
        else:
            data = call_rollout_fn(
                self.generate_rollout, self.args, rollout_id, self.data_source, evaluation=False
            )
        metrics = data.metrics
        data = data.samples
        # flatten the data if it is a list of lists
        while isinstance(data[0], list):
            data = list(itertools.chain.from_iterable(data))

        if not self.args.disable_rollout_trim_samples:
            global_batch_size = self.args.global_batch_size
            if self.args.use_dynamic_global_batch_size:
                logger.info(f"Collected {len(data)} samples from rollout to train with dynamic global batch size")
                # TODO: this is a temporary solution, we should directly save dynamic_global_batch_size to rollout data
                self._dynamic_global_batch_size = self._compute_dynamic_global_batch_size(len(data))
                global_batch_size = self._dynamic_global_batch_size

            if len(data) % global_batch_size != 0:
                trim_len = (len(data) // global_batch_size) * global_batch_size
                if trim_len == 0:
                    raise ValueError(f"Not enough samples {len(data)} for global_batch_size {global_batch_size}")
                origin_data_length = len(data)
                data = data[:trim_len]
                logger.info(f"trim number of samples from {origin_data_length} to {trim_len}")
            logger.info(f"Final collected {len(data)} samples from rollout to train")

    return data, metrics

def _compute_dynamic_global_batch_size(self, num_samples: int) -> int:
    """Calculate dynamic global_batch_size to ensure only one training step.

    Strategy: global_batch_size = num_samples rounded down to a multiple of dp_size
    This ensures num_steps_per_rollout = num_samples // global_batch_size = 1
    """
    dp_size = self.train_parallel_config["dp_size"]
    original_gbs = self.args.global_batch_size

    # Round down to a multiple of dp_size to ensure only one training step
    dynamic_gbs = (num_samples // dp_size) * dp_size

    if dynamic_gbs == 0:
        # Too few samples, use at least dp_size
        dynamic_gbs = dp_size
        logger.warning(f"num_samples={num_samples} < dp_size={dp_size}, using dp_size as global_batch_size")

    # Calculate how many samples will be discarded
    wasted = num_samples - dynamic_gbs

    if dynamic_gbs != original_gbs or wasted > 0:
        logger.info(
            f"Dynamic global_batch_size: {original_gbs} -> {dynamic_gbs} "
            f"(num_samples={num_samples}, dp_size={dp_size}, "
            f"num_steps=1, wasted={wasted})"
        )

    return dynamic_gbs

def _make_picklable(self, obj, depth=0, max_depth=20):
    """Recursively convert an object into a serializable form, handling unpicklable objects."""
    if depth > max_depth:
        return "<max_depth_exceeded>"

    try:
        # Try to pickle it; if that works, return the object as-is
        import pickle
        import io
        pickle.dumps(obj)
        return obj
    except (TypeError, AttributeError, pickle.PicklingError):
        # Not picklable: convert based on the type
        if obj is None or isinstance(obj, (bool, int, float, str, bytes)):
            return obj
        elif isinstance(obj, dict):
            return {k: self._make_picklable(v, depth + 1, max_depth) for k, v in obj.items()}
        elif isinstance(obj, (list, tuple)):
            result = [self._make_picklable(item, depth + 1, max_depth) for item in obj]
            return result if isinstance(obj, list) else tuple(result)
        elif isinstance(obj, set):
            return {self._make_picklable(item, depth + 1, max_depth) for item in obj}
        elif hasattr(obj, '__dict__'):
            # Try to convert it to a dict representation
            try:
                return {
                    '_type': type(obj).__name__,
                    '_module': type(obj).__module__,
                    'data': self._make_picklable(obj.__dict__, depth + 1, max_depth)
                }
            except:
                return f"<unpicklable: {type(obj).__name__}>"
        else:
            # Anything else that cannot be serialized: return its string representation
            return f"<unpicklable: {type(obj).__name__}>"

def _save_debug_rollout_data(self, data, rollout_id, evaluation: bool):
    # TODO to be refactored (originally Buffer._set_data)
    if (path_template := self.args.save_debug_rollout_data) is not None:
        path = Path(path_template.format(rollout_id=("eval_" if evaluation else "") + str(rollout_id)))
        logger.info(f"Save debug rollout data to {path}")
        path.parent.mkdir(parents=True, exist_ok=True)

        def to_debug_dict(sample):
            sample_dict = sample.to_dict()
            sample_dict.pop("env", None)
            sample_dict.pop("rollout_routed_experts", None)
            sample_dict.pop("rollout_routed_experts_weights", None)
            return sample_dict

        # TODO may improve the format
        if evaluation:
            dump_data = dict(
                samples=[to_debug_dict(sample) for dataset_name, info in data.items() for sample in info["samples"]]
            )
        else:
            dump_data = dict(
                samples=[to_debug_dict(sample) for sample in data],
            )

        # Clean up the data by stripping out unserializable objects
        try:
            clean_dump_data = self._make_picklable(dump_data)
            safe_torch_save_debug(dict(rollout_id=rollout_id, **clean_dump_data), path)
        except Exception as e:
            logger.error(f"Failed to save debug rollout data: {e}")
            # Fall back to saving a simplified version
            try:
                simplified_data = {
                    'rollout_id': rollout_id,
                    'num_samples': len(dump_data.get('samples', [])),
                    'error': str(e)
                }
                torch.save(simplified_data, path)
                logger.warning(f"Saved simplified debug data instead due to serialization error")
            except Exception as e2:
                logger.error(f"Failed to save even simplified data: {e2}")

def _post_process_rewards(self, samples: list[Sample] | list[list[Sample]]):
    if self.custom_reward_post_process_func is not None:
        return self.custom_reward_post_process_func(self.args, samples)

    raw_rewards = [sample.get_reward_value(self.args) for sample in samples]

    # DAPO Soft Overlong Punishment: add a length penalty to the reward that feeds advantage
    # computation, while keeping raw_rewards as the pure task reward for logging. The penalty is
    # only applied when the reward is a plain scalar (dict/multi-key rewards are left untouched).
    shaped_rewards = raw_rewards
    if getattr(self.args, "overlong_buffer_len", 0):
        if all(isinstance(r, (int, float)) for r in raw_rewards):
            shaped_rewards = [
                r + compute_overlong_penalty(self.args, sample.response_length)
                for r, sample in zip(raw_rewards, samples, strict=True)
            ]
        else:
            logger.warning(
                "overlong_buffer_len is set but rewards are non-scalar; "
                "skipping soft overlong punishment for this batch."
            )

    if (
        self.args.advantage_estimator in ["grpo", "gspo", "reinforce_plus_plus_baseline"]
        and self.args.rewards_normalization
    ):
        # group norm
        rewards = torch.tensor(shaped_rewards, dtype=torch.float)
        if rewards.shape[-1] == self.args.n_samples_per_prompt * self.args.rollout_batch_size:
            rewards = rewards.reshape(-1, self.args.n_samples_per_prompt)
        else:
            # when samples count are not equal in each group
            rewards = rewards.view(-1, rewards.shape[-1])
        mean = rewards.mean(dim=-1, keepdim=True)
        rewards = rewards - mean

        if self.args.advantage_estimator in ["grpo", "gspo"] and self.args.grpo_std_normalization:
            std = rewards.std(dim=-1, keepdim=True)
            rewards = rewards / (std + 1e-6)

        return raw_rewards, rewards.flatten().tolist()

    return raw_rewards, shaped_rewards

def _convert_samples_to_train_data(self, samples: list[Sample] | list[list[Sample]]):
    """
    Convert inference generated samples to training data.
    """
    if self.custom_convert_samples_to_train_data_func is not None:
        return self.custom_convert_samples_to_train_data_func(self.args, samples)

    raw_rewards, rewards = self._post_process_rewards(samples)

    assert len(raw_rewards) == len(samples)
    assert len(rewards) == len(samples)

    # --critic-exclude-overlong-penalty: ship a second per-sample reward without the soft
    # overlong punishment for the critic's regression target. The penalty is additive, so
    # subtracting it from the shaped reward is exact. Absent the flag this branch adds
    # nothing and the batch is unchanged.
    critic_rewards = None
    if getattr(self.args, "critic_exclude_overlong_penalty", False):
        if (
            self.custom_reward_post_process_func is None
            and getattr(self.args, "overlong_buffer_len", 0)
            and all(isinstance(r, (int, float)) for r in raw_rewards)
        ):
            critic_rewards = [
                r - compute_overlong_penalty(self.args, sample.response_length)
                for r, sample in zip(rewards, samples, strict=True)
            ]
        else:
            logger.warning(
                "critic_exclude_overlong_penalty is set but no overlong penalty was applied "
                "(custom reward post-process, non-scalar rewards, or overlong_buffer_len=0); "
                "critic rewards fall back to the shaped rewards."
            )
            critic_rewards = list(rewards)

    train_data = {
        "tokens": [sample.tokens for sample in samples],
        "response_lengths": [sample.response_length for sample in samples],
        # some reward model, e.g. remote rm, may return multiple rewards,
        # we could use key to select the reward.
        "rewards": rewards,
        "raw_reward": raw_rewards,
        "truncated": [1 if sample.status == Sample.Status.TRUNCATED else 0 for sample in samples],
        "sample_indices": [sample.index for sample in samples],
    }
    if critic_rewards is not None:
        train_data["critic_rewards"] = critic_rewards

    # loss mask
    # TODO: compress the loss mask
    loss_masks = []
    for sample in samples:
        # always instantiate loss_mask if not provided
        if sample.loss_mask is None:
            sample.loss_mask = [1] * sample.response_length

        assert (
            len(sample.loss_mask) == sample.response_length
        ), f"loss mask length {len(sample.loss_mask)} != response length {sample.response_length}"
        if sample.remove_sample or sample.metadata.get("env_error"):
            sample.loss_mask = [0] * sample.response_length
        # DAPO Overlong Filtering: drop truncated (length-capped) samples from the gradient.
        if getattr(self.args, "overlong_filtering", False) and sample.status == Sample.Status.TRUNCATED:
            sample.loss_mask = [0] * sample.response_length
        loss_masks.append(sample.loss_mask)
    train_data["loss_masks"] = loss_masks

    # overwriting the raw reward
    if samples[0].metadata and "raw_reward" in samples[0].metadata:
        train_data["raw_reward"] = [sample.metadata["raw_reward"] for sample in samples]

    if any(sample.metadata.get("env_error") for sample in samples):
        train_data["env_error"] = [1 if sample.metadata.get("env_error") else 0 for sample in samples]

    # For rollout buffer
    if samples[0].metadata and "round_number" in samples[0].metadata:
        train_data["round_number"] = [sample.metadata["round_number"] for sample in samples]

    # Add rollout log probabilities for off-policy correction
    if samples[0].rollout_log_probs is not None:
        train_data["rollout_log_probs"] = [sample.rollout_log_probs for sample in samples]

    if samples[0].rollout_routed_experts is not None:
        train_data["rollout_routed_experts"] = [sample.rollout_routed_experts for sample in samples]

"""Reusable execution plans for synchronous sum reductions."""
from functools import partial

import torch.distributed as dist

_plans = {}


def _size_class(numel: int) -> str:
    if numel <= 64:
        return "small"
    if numel <= 4096:
        return "medium"
    return "large"


def _signature(tensor, group):
    return (
        dist.get_backend(group),
        dist.get_world_size(group),
        dist.get_rank(group),
        tensor.device.type,
        tensor.device.index,
        tensor.dtype,
        _size_class(tensor.numel()),
    )


def reduce_sum(tensor, group=None):
    if group is None:
        group = dist.group.WORLD
    key = _signature(tensor, group)
    plan = _plans.get(key)
    if plan is None:
        plan = partial(dist.all_reduce, group=group, op=dist.ReduceOp.SUM)
        _plans[key] = plan
    return plan(tensor)


def clear():
    _plans.clear()

import logging
import os
from contextlib import contextmanager

import torch
import torch.distributed as dist

from miles.utils.memory_utils import print_memory

logger = logging.getLogger(__name__)

old_new_group_dict = {}


def monkey_patch_torch_dist():
    pid = os.getpid()
    if pid in old_new_group_dict:
        assert dist.old_new_group == old_new_group_dict[pid]
        return

    logger.info("Applying monkey patch to torch.distributed")

    old_new_group = dist.new_group
    old_new_group_dict[pid] = old_new_group
    dist.old_new_group = old_new_group

    def new_group(*args, **kwargs):
        group = old_new_group(*args, **kwargs)
        # skip none nccl group.
        if len(args) >= 3 and args[2] == "gloo" or "backend" in kwargs and kwargs["backend"] == "gloo":
            return group

        # Get ranks from arguments
        if len(args) >= 1 and args[0] is not None:
            ranks = args[0]
        elif "ranks" in kwargs and kwargs["ranks"] is not None:
            ranks = kwargs["ranks"]
        else:
            # If no ranks specified, use all ranks in world
            ranks = list(range(dist.get_world_size()))

        if len(ranks) == 1:
            return group

        group = ReloadableProcessGroup(group, ranks)
        return group

    dist.new_group = new_group

    def get_new_function(func):
        def new_function(*args, **kwargs):
            args = tuple([arg.group if isinstance(arg, ReloadableProcessGroup) else arg for arg in args])
            kwargs = {k: (v.group if isinstance(v, ReloadableProcessGroup) else v) for k, v in kwargs.items()}
            with _wrap_low_level_call():
                return func(*args, **kwargs)

        return new_function

    dist.get_rank = get_new_function(dist.get_rank)
    dist.get_world_size = get_new_function(dist.get_world_size)
    dist.get_backend = get_new_function(dist.get_backend)
    dist.get_global_rank = get_new_function(dist.get_global_rank)
    dist.get_group_rank = get_new_function(dist.get_group_rank)
    dist.get_process_group_ranks = get_new_function(dist.get_process_group_ranks)

    dist.all_reduce = get_new_function(dist.all_reduce)
    dist.all_gather = get_new_function(dist.all_gather)
    dist.all_gather_into_tensor = get_new_function(dist.all_gather_into_tensor)
    dist.all_gather_object = get_new_function(dist.all_gather_object)
    dist.all_to_all = get_new_function(dist.all_to_all)
    dist.all_to_all_single = get_new_function(dist.all_to_all_single)
    dist.broadcast = get_new_function(dist.broadcast)
    dist.reduce = get_new_function(dist.reduce)
    dist.reduce_scatter = get_new_function(dist.reduce_scatter)
    dist.reduce_scatter_tensor = get_new_function(dist.reduce_scatter_tensor)
    dist.scatter = get_new_function(dist.scatter)
    dist.gather = get_new_function(dist.gather)
    dist.barrier = get_new_function(dist.barrier)
    dist.send = get_new_function(dist.send)
    dist.recv = get_new_function(dist.recv)
    dist._coalescing_manager = get_new_function(dist._coalescing_manager)

    # p2p
    old_isend = dist.isend
    old_irecv = dist.irecv

    dist.isend = get_new_function(dist.isend)
    dist.irecv = get_new_function(dist.irecv)

    def get_new_p2pop_function(func):
        def new_function(*args, **kwargs):
            def convert(arg):
                if isinstance(arg, ReloadableProcessGroup):
                    return arg.group
                elif arg == dist.isend:
                    arg = old_isend
                elif arg == dist.irecv:
                    arg = old_irecv
                return arg

            args = (convert(arg) for arg in args)
            kwargs = {k: convert(v) for k, v in kwargs.items()}
            return func(*args, **kwargs)

        return new_function

    dist.P2POp.__new__ = get_new_p2pop_function(dist.P2POp.__new__)
    dist.P2POp.__init__ = get_new_p2pop_function(dist.P2POp.__init__)


class ReloadableProcessGroup(torch.distributed.ProcessGroup):
    GROUPS = {}

    def __init__(self, group, ranks):
        super().__init__(
            rank=dist.get_rank(group),
            size=dist.get_world_size(group),
        )
        self.group = group
        self.group_info = {
            "ranks": ranks,
        }
        pid = os.getpid()
        if pid not in ReloadableProcessGroup.GROUPS:
            ReloadableProcessGroup.GROUPS[pid] = []
        ReloadableProcessGroup.GROUPS[pid].append(self)

    def __getattr__(self, name):
        return getattr(self.group, name)

    @staticmethod
    def destroy_process_groups():
        pid = os.getpid()
        for reloadable_group in ReloadableProcessGroup.GROUPS.get(pid, []):
            if reloadable_group.group is None:
                continue
            try:
                dist.destroy_process_group(reloadable_group.group)
            except ValueError as e:
                logger.warning(
                    f"Process group already invalid/destroyed; skipping cleanup. Exception: {e}",
                    exc_info=True,
                )

            del reloadable_group.group
            reloadable_group.group = None

    @staticmethod
    def reload_process_groups():
        pid = os.getpid()
        reloadable_groups = ReloadableProcessGroup.GROUPS.get(pid, [])
        logger.info(f"Reloading {len(reloadable_groups)} process groups in pid {pid}")
        old_new_group = old_new_group_dict.get(pid)
